sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float exposure;
uniform float contrast;
uniform float temperature;
uniform float tint;
uniform float highlights;
uniform float shadows;
uniform float saturation;
uniform float vibrance;
uniform float liftHue;
uniform float liftAmount;
uniform float gammaHue;
uniform float gammaAmount;
uniform float gainHue;
uniform float gainAmount;
uniform float vignette;
uniform float grain;

float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }

float3 chroma(float hue) {
    float3 k = clamp(abs(fract(hue / 360.0 + float3(1.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
    return k - luma(k);
}

float rand(float2 co) {
    return fract(sin(dot(co, float2(12.9898, 78.233))) * 43758.5453);
}

half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 rgb = float3(c.rgb) / float(c.a);

    // 1. Exposure
    rgb *= exp2(exposure);

    // 2. White Balance (Temperature & Tint)
    rgb.r += temperature * 0.12;
    rgb.b -= temperature * 0.12;
    rgb.g += tint * 0.10;
    rgb = max(rgb, float3(0.0));

    // 3. Highlights & Shadows
    float lum = luma(rgb);
    float shadowMask = 1.0 - smoothstep(0.0, 0.5, lum);
    float highlightMask = smoothstep(0.5, 1.0, lum);
    rgb += shadowMask * shadows * 0.25;
    rgb += highlightMask * highlights * 0.25;
    rgb = max(rgb, float3(0.0));

    // 4. Contrast (S-curve centered at 0.5)
    rgb = (rgb - 0.5) * (1.0 + contrast) + 0.5;
    rgb = max(rgb, float3(0.0));

    // 5. 3-Way Lift / Gamma / Gain Color Wheels
    float3 lift = 0.4 * chroma(liftHue) * liftAmount;
    float3 gain = 1.0 + chroma(gainHue) * gainAmount;
    float3 gamma = max(1.0 + chroma(gammaHue) * gammaAmount, float3(0.05));
    rgb = pow(max(gain * (rgb + lift * (1.0 - rgb)), float3(0.0)), 1.0 / gamma);

    // 6. Saturation & Vibrance
    float newLum = luma(rgb);
    float currentSat = max(max(rgb.r, rgb.g), rgb.b) - min(min(rgb.r, rgb.g), rgb.b);
    float vibAmount = vibrance * (1.0 - currentSat);
    rgb = mix(float3(newLum), rgb, saturation + vibAmount);

    // 7. Vignette
    if (vignette > 0.01) {
        float2 uv = coord / size - 0.5;
        float d = length(uv * float2(1.0, size.y / size.x)) * 1.414;
        float vig = clamp(1.0 - smoothstep(0.4, 1.2, d) * vignette, 0.0, 1.0);
        rgb *= vig;
    }

    // 8. Film Grain
    if (grain > 0.01) {
        float noise = (rand(coord + float2(time * 12.34, time * 56.78)) - 0.5) * grain * 0.25;
        rgb += noise;
    }

    rgb = clamp(rgb, 0.0, 1.0);
    return half4(half3(rgb) * c.a, c.a);
}
